const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['補助款可以拿去買禮品嗎','禮品'],['補助款可以買便當嗎','餐點'],['補助款發票買日常用品行不行','日常用品'],['補助經費能買文具嗎','日常用品'],
['補助款可以付理事長車馬費嗎','一般不行'],['補助款可以給理監事出席費嗎','無給職'],
['補助計畫改了內容要先報嗎','要先報'],['補助的活動日期改了要不要通知縣府','要先報'],
['活動沒辦成補助款要還嗎','繳回'],['補助的活動取消了錢怎麼辦','繳回'],
['核銷忘記了怎麼辦','註銷'],['補助核銷拖到過年怎麼辦','註銷'],
['核銷發票抬頭要開誰','單據抬頭'],
['收據跟發票哪個可以核銷','領款收據'],
['核銷單據要留多久','10年'],['補助的發票要保存幾年','10年'],
['補助被縣府退回怎麼辦','原因'],['核銷被退回要怎麼辦','補正'],
['補助款是不是一定要先墊','核定函'],['補助款什麼時候會撥下來','核定函'],
['同一個活動可以申請兩份補助嗎','不能向縣府兩個單位'],
['協會可以對外募款嗎','公益性社團法人'],
['街頭發傳單請大家捐款可以嗎','勸募'],
];
const no=['合作社補助款可以買禮品嗎','魅力社區補助款可以買便當嗎','社區發展協會核銷忘記了怎麼辦','基金會可以對外募款嗎','宗教團體補助被退回怎麼辦','補助旅遊可以嗎','合作社可以對外募款嗎','理事長車馬費可以領嗎'];
const pat=/補助款能不能買禮品|補助款可以付理事長或理監事|補助計畫要改內容|活動沒辦成或取消|補助核銷忘記或超過|核銷要附領款收據和各項|核銷被退回|補助款要不要先墊|協會可以對外募款嗎/;
let bad=0;
for(const [q,k] of yes){const x=A(q);if(!x||!x.direct||!(x.summary+x.title).includes(k)){console.error('FAIL',q,x&&x.title);bad++;}}
for(const q of no){const x=A(q);if(x&&typeof x==='object'&&pat.test(x.title)){console.error('OVERTRIGGER',q,x.title);bad++;}}
if(bad)throw new Error('patrol60 failed '+bad);console.log('ok');
